WITH Src AS (SELECT * FROM order_items WHERE unit_price < 310 AND unit_price > 130), order_id_summary AS (SELECT order_id, product_id, MIN(quantity) AS min_quantity, MAX(unit_price) - MIN(unit_price) AS unit_price_range FROM Src GROUP BY order_id, product_id) SELECT order_id, product_id, unit_price_range FROM order_id_summary WHERE unit_price_range < 74 ORDER BY unit_price_range DESC;
